import{_ as n,c as t,o as s,j as a,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"南軒易說","description":"南軒易說 - 南軒易說","frontmatter":{"title":"南軒易說","description":"南軒易說 - 南軒易說"},"headers":[],"relativePath":"classics/nanxuan/001.md","filePath":"classics/nanxuan/001.md"}'),r={name:"classics/nanxuan/001.md"};function c(o,e,i,p,d,u){return s(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"南軒易說",tabindex:"-1"},[l("南軒易說 "),a("a",{class:"header-anchor",href:"#南軒易說","aria-label":"Permalink to “南軒易說”"},"​")],-1),a("p",null,"欽定四庫全書經部一",-1),a("p",null,"易類提要",-1),a("p",null,"臣 等謹案：南軒易說，宋張栻撰。案曹學佺蜀中廣記載是書十一卷，以為張浚所作。考浚紫巖易傳，其本猶存，與此別為一書，學佺殊誤。朱彝尊經義考亦作十一卷，注云「未見」，又引董真卿說已闕乾、坤二卦。此本乃嘉興曹溶從至元壬辰贛州路儒學學正胡順父刊本傳寫，並六十四卦皆佚之，僅始於繫辭「天一地二」一章，較真卿所見彌為殘缺。然卷端題曰「繫辭上卷下」，而順父序稱「魯人東泉王公分司廉訪章貢等路，公餘講論，嘗誦伊川易傳，特闕繫辭，留心訪求，因得南軒解說易系，繕寫家藏，儻合以並傳，斯為完書。乃出示知事吳將仕，刊之學宮，以補遺缺，使與周易程氏傳大字舊本同傳於世」云云。是初刊此書，亦僅託始於繫辭，溶所傳寫，僅佚其上卷之上耳。序末有鉤摹舊本三小印：一作「謙卦」；一曰「贛州胡氏」，知順父即贛人；一曰和卿，蓋其字也。乾隆四十六年二月恭校上。",-1),a("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。南軒易說序",-1),a("p",null,"昔尹和靖語學者祁寬曰：「與其讀他書，不若專讀易；與其看伊川雜說，不若專看伊川易傳。」又曰：「一日只念一卦，閒時看繫辭。」周易程氏傳止於卦而不及系，非不及也，以繫辭為易大傳，不暇及也。然易系曰：",-1),a("p",null,"「易有聖人之道四焉：以言者尚其辭，以動者尚其變，以制器者尚其象，以卜筮者尚其佔。」其通論一經之大體如此，不傳奚可？伊川議論，雖間見於遺書，而終未完，學者惜之。至元壬辰，魯人東泉王公分司廉訪章貢等路，公餘講論，因言辭謝衰病，家食數年，從事於易，嘗誦伊川易傳，特闕繫辭，留心訪求，遂得南軒解說易系，繕寫家藏，好玩如寶。聖人之言：「無有師保，如臨父母。」欽哉欽哉！儻合以並傳，斯為完書。乃出示知事吳將仕及路學宿儒，議若命工刊之學宮，以補遺闕，使與周易程氏傳大字舊本並行於世，可乎？將仕洎諸儒覆命曰：「斯文也，蓋有待於今日也，後之學者幸莫大焉。」順父承命校正，敬錄以付匠氏，並序其槩於後。是歲季冬既望，贛州路儒學學正權管學事胡順父序。",-1)])])}const f=n(r,[["render",c]]);export{_ as __pageData,f as default};
